namespace Vnecoms\VendorsSellerList\Block;


use Magento\Framework\View\Element\Template;

class Seller extends \Magento\Framework\View\Element\Template implements \Magento\Framework\DataObject\IdentityInterface
{
    protected $_template = 'Vnecoms_VendorsSellerList::sellers.phtml';

    /** @var \Vnecoms\VendorsSellerList\Helper\Data  */
    protected $sellerListHelper;

    public function __construct(
        Template\Context $context,
        \Vnecoms\VendorsSellerList\Helper\Data $sellerListHelper,
        array $data = []
    ){
        parent::__construct($context, $data);
        $this->sellerListHelper = $sellerListHelper;
    }

    protected function _prepareLayout()
    {
        $this->setTemplate($this->_template);
        return parent::_prepareLayout(); // TODO: Change the autogenerated stub
    }

    public function toHtml()
    {
        return parent::toHtml(); // TODO: Change the autogenerated stub
    }

    /**
     * @return string
     */
    public function getSellerListHtml()
    {
        return $this->getChildHtml('seller_list');
    }

    public function getIdentities(){
        return ['vnecoms_seller_list'];
    }
}